  5	public class ActivitySelection {
  6	    private static final Comparator<Activity> BY_FINISH_TIME =
  7	        Comparator.comparingInt(Activity::finishTime);
  8	
  9	    private ActivitySelection() {
 10	    }
 11	
 12	    public static int activitySelection(int[] start, int[] finish) {
 13	        return maximumCompatibleActivityCount(start, finish);
 14	    }
 15	
 16	    public static int maximumCompatibleActivityCount(int[] start, int[] finish) {
 17	        return selectMaximumCompatibleActivities(start, finish).length;
 18	    }
 19	
 20	    public static int[][] selectMaximumCompatibleActivities(int[] start, int[] finish) {
 21	        return ActivitySchedule.fromParallelArrays(start, finish).toSelectionPairs();
 22	    }
 23	
 24	    public static void main(String[] args) {
 25	        int[] start = {1, 3, 0, 5, 8, 5};
 26	        int[] finish = {2, 4, 6, 7, 9, 9};
 27	
 28	        System.out.println(activitySelection(start, finish));
 29	    }
 30	
 31	    private static final class Activity {
 32	        private final int startTime;
 33	        private final int finishTime;
 34	
 35	        private Activity(int startTime, int finishTime) {
 36	            this.startTime = startTime;
 37	            this.finishTime = finishTime;
 38	        }
 39	
 40	        private int finishTime() {
 41	            return finishTime;
 42	        }
 43	
 44	        private boolean canFollow(Activity other) {
 45	            return startTime > other.finishTime;
 46	        }
 47	
 48	        private int[] toPair() {
 49	            return new int[] {startTime, finishTime};
 50	        }
 51	
 52	        @Override
 53	        public String toString() {
 54	            return "[" + startTime + ", " + finishTime + "]";
 55	        }
 56	    }
 57	
 58	    private static final class ActivitySchedule {
 59	        private final Activity[] activities;
 60	
 61	        private ActivitySchedule(Activity[] activities) {
 62	            this.activities = activities;
 63	        }
 64	
 65	        private static ActivitySchedule fromParallelArrays(int[] start, int[] finish) {
 66	            validateInputs(start, finish);
 67	
 68	            Activity[] activities = new Activity[start.length];
 69	            for (int i = 0; i < start.length; i++) {
 70	                activities[i] = new Activity(start[i], finish[i]);
 71	            }
 72	
 73	            Arrays.sort(activities, BY_FINISH_TIME);
 74	            return new ActivitySchedule(activities);
 75	        }
 76	
 77	        private int countSelectedActivities() {
 78	            return selectCompatibleActivities().length;
 79	        }
 80	
 81	        private int[][] toSelectionPairs() {
 82	            Activity[] selectedActivities = selectCompatibleActivities();
 83	            int[][] selectedPairs = new int[selectedActivities.length][2];
 84	            for (int i = 0; i < selectedActivities.length; i++) {
 85	                selectedPairs[i] = selectedActivities[i].toPair();
 86	            }
 87	            return selectedPairs;
 88	        }
 89	
 90	        private Activity[] selectCompatibleActivities() {
 91	            if (activities.length == 0) {
 92	                return new Activity[0];
 93	            }
 94	
 95	            Activity[] selectedActivities = new Activity[activities.length];
 96	            int selectedCount = 1;
 97	            Activity lastSelected = activities[0];
 98	            selectedActivities[0] = lastSelected;
 99	
100	            // Greedily keep the earliest-finishing compatible activity.
101	            for (int i = 1; i < activities.length; i++) {
102	                Activity current = activities[i];
103	                if (current.canFollow(lastSelected)) {
104	                    selectedActivities[selectedCount] = current;
105	                    selectedCount++;
106	                    lastSelected = current;
107	                }
108	            }
109	
110	            return Arrays.copyOf(selectedActivities, selectedCount);
111	        }
112	
113	        private static void validateInputs(int[] start, int[] finish) {
114	            Objects.requireNonNull(start, "start must not be null");
115	            Objects.requireNonNull(finish, "finish must not be null");
116	
117	            if (start.length != finish.length) {
118	                throw new IllegalArgumentException("start and finish must have the same length");
119	            }
120	        }
121	    }
122	}

