 54	    private static void assertLegacyAlias(SelectionCase testCase) {
 55	        assertEquals(
 56	            ActivitySelection.maximumCompatibleActivityCount(
 57	                testCase.startTimes(),
 58	                testCase.finishTimes()
 59	            ),
 60	            ActivitySelection.activitySelection(testCase.startTimes(), testCase.finishTimes()),
 61	            testCase.message() + " through the legacy alias"
 62	        );
 63	    }
 64	
 65	    private static void assertSelectedActivities(SelectionCase testCase) {
 66	        assertDeepEquals(
 67	            testCase.expectedActivities(),
 68	            ActivitySelection.selectMaximumCompatibleActivities(
 69	                testCase.startTimes(),
 70	                testCase.finishTimes()
 71	            ),
 72	            testCase.message() + " with the expected chosen activities"
 73	        );
 74	    }
 75	
 76	    private static void assertSelectionCount(SelectionCase testCase) {
 77	        assertEquals(
 78	            testCase.expectedCount(),
 79	            ActivitySelection.maximumCompatibleActivityCount(
 80	                testCase.startTimes(),
 81	                testCase.finishTimes()
 82	            ),
 83	            testCase.message()
 84	        );
 85	    }
 86	
 87	    private static void assertDeepEquals(int[][] expected, int[][] actual, String message) {
 88	        if (!Arrays.deepEquals(expected, actual)) {
 89	            throw new AssertionError(
 90	                message
 91	                    + ": expected "
 92	                    + Arrays.deepToString(expected)
 93	                    + " but got "
 94	                    + Arrays.deepToString(actual)
 95	            );
 96	        }
 97	    }
 98	
 99	    private static void assertEquals(int expected, int actual, String message) {
100	        if (expected != actual) {
101	            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
102	        }
103	    }
104	
105	    private static void assertThrows(
106	        Class<? extends Throwable> expected,
107	        ThrowingRunnable runnable,
108	        String message
109	    ) {
110	        try {
111	            runnable.run();
112	        } catch (Throwable actual) {
113	            if (expected.isInstance(actual)) {
114	                return;
115	            }
116	            throw new AssertionError(
117	                message + ": expected " + expected.getSimpleName() + " but got " + actual.getClass().getSimpleName(),
118	                actual
119	            );
120	        }
121	
122	        throw new AssertionError(message + ": expected " + expected.getSimpleName() + " to be thrown");
123	    }
124	
125	    @FunctionalInterface
126	    private interface ThrowingRunnable {
127	        void run() throws Throwable;
128	    }
129	
130	    private record SelectionCase(
131	        int expectedCount,
132	        int[] startTimes,
133	        int[] finishTimes,
134	        int[][] expectedActivities,
135	        String message
136	    ) {
137	    }
138	}

